-- ZOT Mock Challenge: Round 1 questions (70 questions, 10 per subject)
-- Run AFTER mock-challenge.sql. Safe to re-run: it replaces Round 1's questions.
-- Round 1 opens Sunday 13 Dec 2026, 10:00 AM Nigeria time. Change starts_at below if needed.

insert into public.mock_challenges (round_no, title, starts_at, closes_at, duration_minutes, published)
values (1, 'Mock Challenge: Round 1', '2026-12-13 10:00:00+01', '2026-12-13 13:00:00+01', 45, true)
on conflict (round_no) do nothing;

delete from public.mock_questions
 where challenge_id = (select id from public.mock_challenges where round_no = 1);

